            'CREATE TABLE marco_authorization_grants (\n\tgrant_id CHAR(32) NOT NULL, \n\tgeneration_id CHAR(32) NOT NULL, \n\ttask_id CHAR(32) NOT NULL, \n\toperation_id CHAR(32), \n\tfield_name VARCHAR(128) NOT NULL, \n\tbefore_value JSON NOT NULL, \n\tafter_value JSON NOT NULL, \n\treason TEXT NOT NULL, \n\tactor VARCHAR(256) NOT NULL, \n\trun_id CHAR(32) NOT NULL, \n\trequest_id CHAR(32) NOT NULL, \n\tcommand_execution_id CHAR(32) NOT NULL, \n\tgranted_at DATETIME NOT NULL, \n\tCONSTRAINT pk_marco_authorization_grants PRIMARY KEY (grant_id), \n\tCONSTRAINT ck_marco_authorization_grants_reason_nonblank CHECK (length(trim(reason)) > 0), \n\tCONSTRAINT uq_marco_grant_semantic_identity UNIQUE (generation_id, task_id, operation_id, field_name, before_value, after_value), \n\tCONSTRAINT fk_marco_authorization_grants_generation_id_authority_generations FOREIGN KEY(generation_id) REFERENCES authority_generations (generation_id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_marco_authorization_grants_task_id_dish_tasks FOREIGN KEY(task_id) REFERENCES dish_tasks (task_id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_marco_authorization_grants_operation_id_workflow_operations FOREIGN KEY(operation_id) REFERENCES workflow_operations (operation_id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_marco_authorization_grants_run_id_service_runs FOREIGN KEY(run_id) REFERENCES service_runs (run_id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_marco_authorization_grants_request_id_service_requests FOREIGN KEY(request_id) REFERENCES service_requests (request_id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_marco_authorization_grants_command_execution_id_command_executions FOREIGN KEY(command_execution_id) REFERENCES command_executions (execution_id) ON DELETE RESTRICT\n)',
            "CREATE TABLE marco_authorization_states (\n\tgrant_id CHAR(32) NOT NULL, \n\tstate VARCHAR(16) NOT NULL, \n\treservation_token CHAR(32), \n\treservation_request_id CHAR(32), \n\tconsumed_result_id CHAR(32), \n\tauthorization_revision BIGINT NOT NULL, \n\tupdated_at DATETIME NOT NULL, \n\tCONSTRAINT pk_marco_authorization_states PRIMARY KEY (grant_id), \n\tCONSTRAINT ck_marco_authorization_states_state_allowed CHECK (state IN ('available','reserved','consumed')), \n\tCONSTRAINT ck_marco_authorization_states_positive_revision CHECK (authorization_revision > 0), \n\tCONSTRAINT ck_marco_authorization_states_state_payload_consistent CHECK ((state = 'available' AND reservation_token IS NULL AND reservation_request_id IS NULL AND consumed_result_id IS NULL) OR (state = 'reserved' AND reservation_token IS NOT NULL AND reservation_request_id IS NOT NULL AND consumed_result_id IS NULL) OR (state = 'consumed' AND reservation_token IS NOT NULL AND reservation_request_id IS NOT NULL AND consumed_result_id IS NOT NULL)), \n\tCONSTRAINT fk_marco_authorization_states_grant_id_marco_authorization_grants FOREIGN KEY(grant_id) REFERENCES marco_authorization_grants (grant_id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_marco_authorization_states_reservation_token UNIQUE (reservation_token), \n\tCONSTRAINT fk_marco_authorization_states_reservation_request_id_service_requests FOREIGN KEY(reservation_request_id) REFERENCES service_requests (request_id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_marco_authorization_states_consumed_result_id UNIQUE (consumed_result_id)\n)",
